function listeningTaste(){const values=new Map();for(let i=0;i<songs.length;i++){const t=songs[i],artist=t.a.split(/,| & /)[0].trim(),key=artistKey(artist);const weight=Math.min(20,(Number(state.listenSeconds[i])||0)/90)+(state.favorites.includes(i)?5:0)+(Number(state.listenCounts[i])||0)*.25-(Number(state.skips[i])||0)*2;if(weight<=0)continue;const current=values.get(key)||{artist,weight:0};current.weight+=weight;values.set(key,current);}return [...values.values()].sort((a,b)=>b.weight-a.weight).slice(0,10).map(t=>({...t,weight:Math.min(50,t.weight)}));}
function automaticQueue(){const excluded=new Set([...state.hiddenSongs,state.song]);const manual=new Set(state.playNext.map(discoveryKey));return state.discoveryQueue.filter(i=>songs[i]&&!excluded.has(i)&&!manual.has(discoveryKey(songs[i]))&&!state.hiddenArtists.some(a=>artistKey(songs[i].a).includes(artistKey(a))));}
async function ensureDiscovery(index=state.song,force=false){const track=songs[index];if(!track)return;const key=discoveryKey(track);if(!force&&state.discoverySeedKey===key&&automaticQueue().length>4)return;if(discoveryPendingKey===key)return discoveryRequest?.promise;discoveryRequest?.controller.abort();const controller=new AbortController();discoveryPendingKey=key;discoveryError='';if(state.discoverySeedKey!==key){state.discoveryQueue=[];state.discoverySeedKey=key;}const work=(async()=>{try{const excluded=[track,...state.playNext,...state.hiddenSongs.map(i=>songs[i]).filter(Boolean)];const payload={seed:{t:track.t,a:track.a,appleId:track.appleId,vid:track.vid},taste:listeningTaste(),hiddenArtists:state.hiddenArtists,exclude:excluded.flatMap(t=>[songIdentity(t),artistKey(t.t).replace(/[^a-z0-9]/g,'')+'|'+artistKey(t.a).replace(/[^a-z0-9]/g,'')]),recent:(state.recentChoices||[]).map(i=>songs[i]&&songIdentity(songs[i])).filter(Boolean),favorites:state.favorites.map(i=>songs[i]&&songIdentity(songs[i])).filter(Boolean),skips:Object.fromEntries(Object.entries(state.skips).filter(([i])=>songs[i]).map(([i,n])=>[songIdentity(songs[i]),n]))};const response=await fetch('/api/recommendations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal});const body=await response.json();if(!response.ok)throw Error(body.error||'No se pudieron cargar las recomendaciones');if(discoveryKey(songs[state.song])!==key)return;state.discoveryQueue=body.tracks.map(mergeCatalogueTrack);state.discoveryGenre=body.genre;save();if(state.page==='home')render();}catch(error){if(error.name!=='AbortError')discoveryError='No se pudieron cargar las recomendaciones. Inténtalo de nuevo.';}finally{if(discoveryPendingKey===key){discoveryPendingKey='';discoveryRequest=null;if(sheet?.kind==='upcoming')drawContinuation();}}})();discoveryRequest={controller,promise:work};return work;}
function drawContinuation(){sheet={kind:'upcoming',index:state.song};sheetHost.hidden=false;const pending=state.playNext.map((track,q)=>{const i=mergeCatalogueTrack(track);return '<div class="queued-track">'+row(i)+'<button data-removequeued="'+q+'" aria-label="Quitar '+esc(track.t)+' de Reproducir después">'+icon('x')+'</button></div>';}).join('');const queue=automaticQueue();let manual='';if(['playlist','album'].includes(state.continuationMode)){const list=state.playContext||[],at=list.indexOf(state.song);const remaining=list.slice(at+1).filter(i=>songs[i]);if(remaining.length)manual='<h3>'+ (state.continuationMode==='album'?'En este álbum':'En tu playlist')+'</h3>'+remaining.map(i=>row(i)).join('');}sheetHost.innerHTML=`<div class="sheet-scrim" data-action="close-sheet"></div><div class="sheet-panel continuation-panel" role="dialog" aria-label="Continue Playing"><div class="top"><h3>Continue Playing</h3><button data-action="close-sheet" aria-label="Cerrar opciones">${icon('x')}</button></div>${pending?'<h3>Reproducir después</h3>'+pending:''}${manual}<h3>Para ti</h3>${queue.map(i=>row(i)).join('')||'<p role="status">'+(discoveryError||(discoveryPendingKey?'Buscando música similar…':'No hay recomendaciones disponibles para esta canción.'))+'</p>'}${discoveryError?'<button data-action="retry-discovery">Reintentar</button>':''}</div>`;icons();}
async function playDiscoveryNext(){const from=state.song;await ensureDiscovery();if(state.song!==from)return;const queue=automaticQueue();if(!queue.length){notice(discoveryError||'No hay recomendaciones disponibles para esta canción.');return;}const next=state.shuffle?queue[Math.floor(Math.random()*Math.min(6,queue.length))]:queue[0];state.discoveryQueue=state.discoveryQueue.filter(i=>i!==next);state.discoverySeedKey=discoveryKey(songs[next]);state.continuationMode='discovery';startTrack(next,{keepContext:true});}


function downloadedPage(){const downloaded=[...window.VitraOffline.items.values()];return back('library','Biblioteca')+'<h1>Descargadas</h1><p>'+downloaded.length+(downloaded.length===1?' canción · ':' canciones · ')+(downloaded.reduce((n,r)=>n+r.size,0)/1048576).toFixed(1)+' MB</p>'+(downloaded.length?downloaded.sort((a,b)=>b.date-a.date).map(r=>row(mergeCatalogueTrack({...r.track,art:r.track.offlineArt||r.track.art}))).join(''):'<p class="empty">Descarga canciones desde su menú para escucharlas sin conexión.</p>');}
async function handleDownload(index){const song=songs[index];if(window.VitraOffline.pending.has(window.VitraOffline.key(song)))return;closeSheet();try{if(window.VitraOffline.has(song)){await window.VitraOffline.remove(song);notice('Descarga eliminada del dispositivo.');}else{notice('Descargando '+song.t+'…');await window.VitraOffline.download(song);notice('Disponible sin conexión: '+song.t);}}catch(e){notice(e.name==='QuotaExceededError'?'No queda espacio para esta descarga.':e.message||'No se pudo guardar la descarga.');}}
window.addEventListener('vitra-downloads-changed',()=>{if(state.page==='downloads')render();if(sheet?.kind==='menu')drawSheet();});
window.VitraOffline.ready.then(()=>{for(const r of window.VitraOffline.items.values())mergeCatalogueTrack({...r.track,art:r.track.offlineArt||r.track.art});});

phone.classList.toggle("reduce-title-motion",state.scrollTitles===false);
let homeCharts=null,homePicks=[],homePersonal=[],homeLoading=false,homePersonalLoading=false,homeError='',homePersonalKey='',homeLastPersonal=0;
function homeTasteKey(){return JSON.stringify({taste:listeningTaste().map(t=>[artistKey(t.artist),Math.round(t.weight/2)]),favorites:state.favorites,artists:state.hiddenArtists,songs:state.hiddenSongs});}
if(state.topPicksCache?.version===1&&state.topPicksCache.key===homeTasteKey()&&Array.isArray(state.topPicksCache.picks))homePicks=state.topPicksCache.picks;
function homePayload(){const taste=listeningTaste();return {taste,hiddenArtists:state.hiddenArtists,exclude:state.hiddenSongs.map(i=>songs[i]&&songIdentity(songs[i])).filter(Boolean),recent:(state.recentChoices||[]).map(i=>songs[i]&&songIdentity(songs[i])).filter(Boolean),favorites:state.favorites.map(i=>songs[i]&&songIdentity(songs[i])).filter(Boolean),skips:Object.fromEntries(Object.entries(state.skips).filter(([i])=>songs[i]).map(([i,n])=>[songIdentity(songs[i]),n]))};}
function homeVisible(track){return !state.hiddenSongs.some(i=>songs[i]&&songIdentity(songs[i])===songIdentity(track))&&!state.hiddenArtists.some(a=>artistKey(track.a).includes(artistKey(a)));}
function homeLabel(text){return String(text||'').replace(/^Apple Music\s*·\s*/i,'').replace('Selección de las listas de Apple Music','Selección de listas regionales');}
function homeShelf(section){const tracks=section.tracks.filter(homeVisible);if(!tracks.length)return '';return `<section class="home-shelf"><h2>${esc(section.title)}</h2>${section.subtitle?`<p class="home-subtitle">${esc(homeLabel(section.subtitle))}</p>`:''}<div class="home-carousel" aria-label="${esc(section.title)}">${tracks.map(track=>{const i=mergeCatalogueTrack(track);return `<article class="home-music-card"><button data-song="${i}" aria-label="Reproducir ${esc(track.t)}"><img src="${esc(track.art)}" alt="Portada de ${esc(track.t)}" loading="lazy" decoding="async"></button><div class="home-caption"><button data-song="${i}"><strong>${esc(track.t)}</strong><small>${esc(track.a)}</small></button><button data-menu="${i}" aria-label="Opciones de ${esc(track.t)}">${icon('ellipsis')}</button></div></article>`;}).join('')}</div></section>`;}
function homeView(){queueMicrotask(loadHome);let content=header('Inicio');content+=topPicksView();content+=newReleasesView();if(homePersonal.length)content+=homePersonal.map(homeShelf).join('');if(homeCharts){content+=homeShelf(homeCharts.sections[0]);content+=`<section class="home-shelf"><h2>Artistas en tendencia</h2><div class="home-carousel home-artists">${homeCharts.artists.map(a=>`<button data-artist="${esc(a.name)}"><img src="${esc(a.photo||'/api/home-portrait/'+a.id)}" alt="${esc(a.name)}" loading="lazy" decoding="async"><span>${esc(a.name)}</span></button>`).join('')}</div></section>`;content+=homeCharts.sections.slice(1).map(homeShelf).join('');}else content+=`<p role="status" class="empty">${homeError||'Cargando lo más escuchado…'}</p>${homeError?'<button class="pill" data-home-retry>Reintentar</button>':''}`;return content;}
async function loadHome(){if(!homeCharts&&!homeLoading&&!homeError){homeLoading=true;try{const r=await fetch('/api/home-charts');const body=await r.json();if(!r.ok)throw Error(body.error);homeCharts=body;}catch(e){homeError='No se pudieron cargar las listas. Comprueba tu conexión.';}finally{homeLoading=false;if(state.page==='home'){const y=main.scrollTop;render();main.scrollTop=y;}}}
 const key=homeTasteKey();if(!listeningTaste().length||homePersonalLoading||(homePersonalKey===key&&Date.now()-homeLastPersonal<120000))return;homePersonalLoading=true;homePersonalKey=key;homeLastPersonal=Date.now();try{const r=await fetch('/api/home-personal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(homePayload())});const body=await r.json();if(!r.ok)throw Error(body.error);if(homeTasteKey()!==key)return;homePersonal=body.sections||[];homePicks=body.picks||[];state.topPicksCache={version:1,key,picks:homePicks};save();}catch{if(!homePersonal.length)homeError='No se pudo actualizar tu mezcla.';}finally{homePersonalLoading=false;if(state.page==='home')render();}}
root.addEventListener('click',event=>{if(event.target.closest('[data-home-retry]')){homeError='';homeLastPersonal=0;loadHome();}});

function topPicksView(){if(!hasTaste())return '';const picks=homePicks.map((p,index)=>({p,index})).filter(({p})=>p.kind==='song'?homeVisible(p.track):!state.hiddenArtists.some(a=>artistKey(p.artist).includes(artistKey(a))));if(!picks.length)return '';return `<section class="home-top-picks"><h2>Selecciones para ti</h2><div class="home-carousel top-picks-carousel" aria-label="Selecciones para ti">${picks.map(({p,index})=>`<button class="top-pick-card ${p.kind==='artist'?'top-pick-artist':''}" data-top-pick="${index}" aria-label="${p.kind==='artist'?'Artista':p.kind==='album'?'Álbum':'Canción'}: ${esc(p.title)}"><span class="top-pick-image"><img src="${esc(p.art||'/icon.png')}" alt="" loading="lazy" decoding="async"></span><span class="top-pick-title">${esc(p.title)}</span></button>`).join('')}</div></section>`;}
root.addEventListener('click',event=>{const button=event.target.closest('[data-top-pick]');if(!button)return;const pick=homePicks[Number(button.dataset.topPick)];if(!pick)return;if(pick.kind==='song'){startTrack(mergeCatalogueTrack(pick.track));return;}if(pick.kind==='artist'){state.artist=pick.artist;navigate('artist');return;}if(pick.kind==='album'){albumCollections.set(pick.album.id,pick.album);state.albumId=pick.album.id;state.artist=pick.artist;navigate('artist-album');}});

// UI integrated inside the main app closure; all library changes use its local save adapter.
state.listeningLog=state.listeningLog&&typeof state.listeningLog==='object'?state.listeningLog:{};
const libraryTools=window.VitraLibraryTools;
let recapKind='week',recapOffset=0;
function recapView(){const recap=libraryTools.summary(state.listeningLog,recapKind,recapOffset),end=new Date(recap.end);end.setDate(end.getDate()-1);const date=d=>d.toLocaleDateString('es',{day:'numeric',month:'short',year:'numeric'}),period=recapKind==='year'?String(recap.start.getFullYear()):recapKind==='month'?recap.start.toLocaleDateString('es',{month:'long',year:'numeric'}):date(recap.start)+' – '+date(end);const mins=Math.round(recap.seconds/60),minutes=mins<60?mins+' min':Math.floor(mins/60)+' h '+mins%60+' min';return back('library','Biblioteca')+`<h1>Tu resumen</h1><div class="recap-periods" role="group" aria-label="Periodo del resumen">${[['week','Semana'],['month','Mes'],['year','Año']].map(([key,label])=>`<button data-recap-kind="${key}" aria-pressed="${key===recapKind}">${label}</button>`).join('')}</div><div class="recap-dates"><button data-recap-offset="-1" aria-label="Periodo anterior">${icon('chevron-left')}</button><strong>${esc(period)}</strong><button data-recap-offset="1" aria-label="Periodo siguiente" ${recapOffset>=0?'disabled':''}>${icon('chevron-right')}</button></div>${recap.seconds>0?`<div class="recap-totals"><div><strong>${minutes}</strong><span>escuchados</span></div><div><strong>${recap.plays}</strong><span>reproducciones</span></div><div><strong>${recap.artists.length}</strong><span>artistas</span></div></div><h2>Tu artista más escuchado</h2><div class="recap-hero"><img src="${esc(recap.artists[0].art||'/icon.png')}" alt="Portada de su música"><div><span>ARTISTA N.º 1</span><h2>${esc(recap.artists[0].name)}</h2><p>${Math.round(recap.artists[0].seconds/60)} min escuchados</p></div></div><h2>Tus canciones</h2>${recap.tracks.slice(0,10).map((t,n)=>`<button class="row recap-track" data-recap-track="${esc(t.id)}"><span class="recap-rank">${n+1}</span><img src="${esc(t.art||'/icon.png')}" alt=""><div class="meta"><strong>${esc(t.t)}</strong><small>${esc(t.a)}</small></div><span class="time">${Math.round(t.seconds/60)} min</span></button>`).join('')}<h2>Tus artistas</h2>${recap.artists.slice(0,5).map((a,n)=>`<div class="row"><span class="recap-rank">${n+1}</span><div class="meta"><strong>${esc(a.name)}</strong><small>${Math.round(a.seconds/60)} min · ${a.plays} reproducciones</small></div></div>`).join('')}`:'<div class="recap-empty">'+icon('chart-no-axes-combined')+'<h2>Tu música cuenta tu historia</h2><p>Escucha canciones en Vitra y aquí aparecerán tus artistas y canciones más escuchados.</p></div>'}<p class="recap-note">Clasificación por tiempo escuchado. Una reproducción cuenta a partir de 30 segundos, o la mitad de una canción más corta. Se registra desde esta actualización y se guarda solo en este dispositivo.</p>`;}
let listeningSession={index:-1,position:0,wall:0,seconds:0,counted:false},lastRecapSave=0;
window.VitraAudio.on('track',e=>{listeningSession={index:e.index,position:0,wall:performance.now(),seconds:0,counted:false};});
window.VitraAudio.on('position',e=>{const audio=window.VitraAudio.audio,wall=performance.now(),previous=listeningSession;
 if(e.index!==previous.index){listeningSession={index:e.index,position:e.position,wall,seconds:0,counted:false};return;}
 const delta=e.position-previous.position,elapsed=(wall-previous.wall)/1000;previous.position=e.position;previous.wall=wall;
 if(delta<0){if(audio.loop&&e.position<2&&previous.seconds>0){previous.seconds=0;previous.counted=false;}return;}
 if(audio.paused||audio.seeking||delta<=0||delta>60||elapsed>60||delta>elapsed*1.25+.3)return;
 const track=songs[e.index];if(!track)return;previous.seconds+=delta;const threshold=Math.min(30,(Number.isFinite(audio.duration)&&audio.duration>0?audio.duration:60)/2),count=!previous.counted&&previous.seconds>=threshold?1:0;if(count)previous.counted=true;
 libraryTools.add(state.listeningLog,track,delta,count);if(Date.now()-lastRecapSave>5000){lastRecapSave=Date.now();save();}
});
window.VitraAudio.on('state',e=>{listeningSession.wall=performance.now();listeningSession.position=window.VitraAudio.audio.currentTime||0;/* Playback-state persistence is handled once by the player listener. */});
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});

let importDraft=null,importProgress='',importBusy=false,importController=null;
function importInstructions(){const service=activeImportService==='apple'?'Apple Music':activeImportService==='spotify'?'Spotify':'Apple Music o Spotify';return `<details class="import-help" open><summary>Cómo importar desde iPhone</summary><ol><li>En Vitra, toca <strong>${service}</strong> arriba.</li><li>Inicia sesión en el servicio si te lo pide y autoriza la lectura de tus playlists.</li><li>Al volver a Vitra, elige la playlist que quieres traer.</li><li>Revisa las canciones encontradas y pulsa <strong>Guardar playlist</strong>.</li></ol><p>No necesitas una cuenta de Vitra. Si aparece «pendiente de activación», usa un archivo mientras se habilita la conexión.</p></details>`;}
function importFileInstructions(){return `<details class="import-help" ${activeImportService==='apple'?'open':''}><summary>Obtener el archivo de Apple Music para iPhone</summary><p>Apple Music en iPhone no tiene una opción para exportar playlists como CSV o XML. Compartir playlist crea un enlace, no el archivo que pide esta opción de Vitra.</p><ol><li>En una Mac, abre Música y selecciona tu playlist de Apple Music.</li><li>Elige <strong>Archivo → Biblioteca → Exportar playlist</strong>. Selecciona <strong>XML</strong> y guarda el archivo en <strong>iCloud Drive</strong>.</li><li>En el iPhone, abre <strong>Archivos → Explorar → iCloud Drive</strong> y comprueba que aparezca el XML.</li><li>Vuelve a Vitra y toca <strong>Elegir archivo de playlist</strong>. Selecciona el XML de iCloud Drive.</li><li>Revisa las canciones encontradas y pulsa <strong>Guardar playlist</strong>.</li></ol><p>Si solo tienes iPhone y no dispones de una Mac, la alternativa es conectar Apple Music directamente a Vitra cuando esa conexión esté activada; así no necesitas exportar un archivo.</p></details><details class="import-help"><summary>Importar un archivo desde iPhone</summary><ol><li>Guarda el archivo CSV, XML, TXT o JSON de tu playlist en <strong>Archivos</strong>, en iCloud Drive o En mi iPhone.</li><li>Toca <strong>Elegir archivo de playlist</strong> y busca ese archivo.</li><li>Espera las coincidencias, revisa el resultado y toca <strong>Guardar playlist</strong>.</li></ol><p>Si recibiste el archivo por correo o mensaje, usa Compartir → Guardar en Archivos primero. El archivo contiene la lista de canciones, no el audio.</p></details><details class="import-help"><summary>Exportar desde Apple Music en Mac</summary><ol><li>Abre Música y selecciona la playlist.</li><li>Ve a <strong>Archivo → Biblioteca → Exportar playlist</strong> y elige <strong>XML</strong>.</li><li>Guarda el XML en iCloud Drive para seleccionarlo desde tu iPhone, o impórtalo en Vitra desde la Mac.</li></ol><p>Para un CSV de Spotify, incluye las columnas de canción y artista.</p></details>`;}

function importView(){return back('playlists','Playlists')+`<h1>Importar playlist</h1><p class="import-intro">Trae tu música de Apple Music o Spotify a tu biblioteca.</p><div class="import-services"><button class="row" data-import-service="apple">${icon('music-2')}<span>Apple Music</span>${icon('chevron-right')}</button><button class="row" data-import-service="spotify">${icon('disc-3')}<span>Spotify</span>${icon('chevron-right')}</button></div>${serviceLists.length?`<div class="import-services">${serviceLists.map(p=>`<button class="row" data-service-playlist="${esc(p.id)}"><span>${esc(p.name)}</span>${icon("chevron-right")}</button>`).join("")}</div>`:""}${importInstructions()}<h2>Desde un archivo</h2><label class="import-file-card">${icon('file-up')}<strong>Elegir archivo de playlist</strong><span>CSV, texto tabulado, XML de Apple Music o JSON</span><input type="file" class="playlist-import-file" accept=".csv,.txt,.tsv,.xml,.json" ${importBusy?'disabled':''}></label>${importFileInstructions()}<div class="import-feedback" role="status">${esc(importProgress)}</div>${importDraft?`<section class="import-review"><h2>${esc(importDraft.title)}</h2><p>${importDraft.tracks.length} canciones · ${importDraft.matches.filter(Boolean).length} encontradas${importDraft.missing?.length?' · '+importDraft.missing.length+' pendientes':''}</p>${importDraft.warnings.map(w=>'<p>'+esc(w)+'</p>').join('')}${importBusy?'<button class="pill" data-import-cancel>Cancelar búsqueda</button>':`<button class="pill import-confirm" data-import-confirm ${importDraft.matches.some(Boolean)?'':'disabled'}>Guardar playlist (${importDraft.matches.filter(Boolean).length})</button>${importDraft.missing?.length?'<button class="pill" data-import-retry>Reintentar pendientes</button>':''}`}<div class="import-preview">${importDraft.tracks.map((t,i)=>`<div class="row"><div class="meta"><strong>${esc(t.t)}</strong><small>${esc(t.a)}</small></div><span>${importDraft.matches[i]?icon('check'):importBusy?icon('ellipsis'):icon('circle-help')}</span></div>`).join('')}</div></section>`:''}`;}
async function matchImport(){if(!importDraft||importBusy)return;importBusy=true;const draft=importDraft,controller=importController=new AbortController();let cursor=0,done=draft.matches.filter(Boolean).length;
 async function worker(){while(cursor<draft.tracks.length&&!controller.signal.aborted){const i=cursor++;if(draft.matches[i])continue;const t=draft.tracks[i];try{const response=await fetch('/api/import/resolve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:t.t,artist:t.a}),signal:controller.signal});const result=await response.json();if(response.ok&&result.match)draft.matches[i]=result.match;}catch(error){if(error.name==='AbortError')break;}done++;importProgress='Buscando coincidencias: '+done+' de '+draft.tracks.length;if(state.page==='import-playlist')render();}}
 render();try{await Promise.all([worker(),worker(),worker()]);}finally{if(importController===controller){importBusy=false;draft.missing=draft.tracks.filter((_,i)=>!draft.matches[i]);importProgress=controller.signal.aborted?'Búsqueda detenida. Puedes guardar las canciones encontradas o reintentar.':'Revisa las coincidencias antes de guardar. Las canciones pendientes no se añadirán.';if(state.page==='import-playlist')render();}}
}
async function readPlaylistFile(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('Elige un archivo de menos de 5 MB.');let text;const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);text=new TextDecoder(bytes[0]===255&&bytes[1]===254?'utf-16le':bytes[0]===254&&bytes[1]===255?'utf-16be':'utf-8').decode(buffer);const parsed=libraryTools.parse(text,file.name);importDraft={...parsed,matches:[],missing:[]};await matchImport();}catch(error){importProgress=error.message;render();}}
function bindLibraryTools(){const file=main.querySelector('.playlist-import-file');if(file)file.onchange=()=>readPlaylistFile(file.files[0]);}
root.addEventListener('click',async event=>{const kind=event.target.closest('[data-recap-kind]'),offset=event.target.closest('[data-recap-offset]'),track=event.target.closest('[data-recap-track]');if(kind){recapKind=kind.dataset.recapKind;recapOffset=0;render();}if(offset){recapOffset=Math.min(0,Math.max(-520,recapOffset+Number(offset.dataset.recapOffset)));render();}if(track){const t=libraryTools.summary(state.listeningLog,recapKind,recapOffset).tracks.find(t=>t.id===track.dataset.recapTrack);if(t)startTrack(mergeCatalogueTrack(t));}
 if(event.target.closest('[data-import-cancel]'))importController?.abort();if(event.target.closest('[data-import-retry]'))matchImport();
 if(event.target.closest('[data-import-confirm]')&&importDraft&&!importBusy){const matched=importDraft.matches.filter(Boolean),indices=matched.map(mergeCatalogueTrack);const id=state.playlists.length;state.playlists.push(importDraft.title);state.playlistData[id]={tracks:[...new Set(indices)],importedAt:new Date().toISOString(),missing:importDraft.missing||[]};state.playlist=id;importDraft=null;importProgress='';save();navigate('playlist');notice('Playlist importada en este dispositivo.');}
 const service=event.target.closest('[data-import-service]');if(service)connectImportService(service.dataset.importService);
});

// Official connection flows. Access credentials stay in memory, outside backups.
let serviceConfig=null,serviceToken='',activeImportService='',serviceLists=[];
async function configImport(){if(!serviceConfig){const r=await fetch('/api/import/config');if(!r.ok)throw Error('No se pudo consultar la conexión.');serviceConfig=await r.json();}return serviceConfig;}
async function serviceCall(action,id){const r=await fetch('/api/import/service',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service:activeImportService,action,id,token:serviceToken})});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo leer el servicio.');return data;}
async function showServiceLists(){importProgress='Cargando tus playlists…';render();const result=await serviceCall('list');serviceLists=result.playlists;importProgress=serviceLists.length?'Elige una playlist para revisar sus canciones.':'No hay playlists disponibles para esta conexión.';render();}
async function connectImportService(service){try{const cfg=await configImport();activeImportService=service;serviceLists=[];
 if(service==='spotify'){
  if(!cfg.spotifyClientId)throw Error('La conexión de Spotify está pendiente de activación. Mientras tanto puedes importar un archivo.');
  if(new URL(cfg.spotifyRedirectUri).origin!==location.origin)throw Error('Abre la dirección principal de Vitra para conectar Spotify.');
  const random=n=>Array.from(crypto.getRandomValues(new Uint8Array(n)),v=>v.toString(16).padStart(2,'0')).join('');const verifier=random(32),nonce=random(24),digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)),challenge=btoa(String.fromCharCode(...new Uint8Array(digest))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  sessionStorage.setItem('vitra-spotify-pkce',JSON.stringify({verifier,nonce,redirect:cfg.spotifyRedirectUri,client:cfg.spotifyClientId,at:Date.now()}));
  const params=new URLSearchParams({response_type:'code',client_id:cfg.spotifyClientId,scope:'playlist-read-private playlist-read-collaborative',redirect_uri:cfg.spotifyRedirectUri,state:nonce,code_challenge_method:'S256',code_challenge:challenge});location.assign('https://accounts.spotify.com/authorize?'+params);return;
 }
 if(!cfg.appleDeveloperToken)throw Error('La conexión de Apple Music está pendiente de activación. Mientras tanto puedes importar un archivo.');
 importProgress='Preparando Apple Music…';render();
 if(!window.MusicKit)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://js-cdn.music.apple.com/musickit/v3/musickit.js';script.onload=resolve;script.onerror=()=>reject(Error('No se pudo abrir Apple Music.'));document.head.append(script);});
 await MusicKit.configure({developerToken:cfg.appleDeveloperToken,app:{name:'Vitra',build:'1.0'}});serviceToken=await MusicKit.getInstance().authorize();await showServiceLists();
 }catch(error){importProgress=error.message;if(state.page==='import-playlist')render();}}
