 const returned=new URLSearchParams(location.search);const saved=sessionStorage.getItem('vitra-spotify-pkce');sessionStorage.removeItem('vitra-spotify-pkce');params.delete('code');params.delete('state');const denied=params.get('error');params.delete('error');window.history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash);
