const artistCheckedAt=new Map(),albumCheckedAt=new Map();
async function loadArtistCollection(name,{force=false,partial=false}={}){const p=profileFor(name);if(!p||collectionPending.has(p.id))return;const now=Date.now();if(!force&&!partial&&now-(artistCheckedAt.get(p.id)||0)<60000)return;artistCheckedAt.set(p.id,now);collectionPending.add(p.id);collectionErrors.delete(p.id);try{const response=await fetch('/api/artist-by-name?q='+encodeURIComponent(name)+(force?'&refresh=1':''),{cache:'no-store'});const body=await response.json();if(!response.ok)throw Error(body.error||'No se pudo actualizar el artista');body.topSongs.forEach(mergeCatalogueTrack);for(const a of [...body.albums,...body.singles])albumCollections.set(a.id,{...albumCollections.get(a.id),...a});if(body.latest){albumCollections.set(body.latest.id,{...albumCollections.get(body.latest.id),...body.latest});body.latest.tracks?.forEach(mergeCatalogueTrack);}const profile={...body,id:p.id};artistCollections.set(p.id,profile);rememberFastArtist(profile);scheduleArtistRecheck(name,profile);if(state.page==='artist'&&!state.playing&&!state.loading)prepareAudio(body.topSongs[0]);save();}catch(error){collectionErrors.set(p.id,'No se pudo actualizar el catálogo. Se volverá a intentar.');}finally{collectionPending.delete(p.id);if(state.page==='artist'&&profileFor(state.artist)?.id===p.id){const y=main.scrollTop;render();main.scrollTop=y;}}}
async function loadFullAlbum(id,{force=false}={}){if(collectionPending.has(id))return;const now=Date.now(),cached=albumCollections.get(id);if(!force&&now-(albumCheckedAt.get(id)||0)<60000)return;albumCheckedAt.set(id,now);collectionPending.add(id);collectionErrors.delete(id);try{const response=await fetch('/api/album/'+encodeURIComponent(id)+(force?'?refresh=1':''),{cache:'no-store'});const body=await response.json();if(!response.ok)throw Error(body.error||'No se pudo actualizar el álbum');body.tracks.forEach(mergeCatalogueTrack);albumCollections.set(id,body);if(state.page==='artist-album'&&!state.playing&&!state.loading)prepareAudio(body.tracks[0]);save();}catch{collectionErrors.set(id,'No se pudo actualizar el álbum. Se volverá a intentar.');}finally{collectionPending.delete(id);if(state.page==='artist-album'&&state.albumId===id){const y=main.scrollTop;render();main.scrollTop=y;}}}
async function loadArtistProfile(name){const key=artistKey(name);if(profileFor(name)||artistPending.has(key))return;artistPending.add(key);try{const response=await fetch('/api/artist-by-name?q='+encodeURIComponent(name));if(!response.ok)throw Error('Artista no disponible');const body=await response.json(),p={id:body.id,name:body.name,photo:body.hero};state.artistProfiles[key]=p;state.artistProfiles[artistKey(p.name)]=p;artistCollections.set(p.id,body);rememberFastArtist(body);scheduleArtistRecheck(name,body);artistCheckedAt.set(p.id,Date.now());for(const a of [...body.albums,...body.singles])albumCollections.set(a.id,{...albumCollections.get(a.id),...a});if(body.latest)albumCollections.set(body.latest.id,{...albumCollections.get(body.latest.id),...body.latest});body.topSongs.forEach(mergeCatalogueTrack);if(state.page==='artist'&&!state.playing&&!state.loading)prepareAudio(body.topSongs[0]);save();if(state.page==='artist'&&artistKey(state.artist)===key)render();}catch{try{const r=await fetch('/api/artists?q='+encodeURIComponent(name));const body=await r.json(),p=body.artists?.find(a=>artistKey(a.name)===key);if(p){state.artistProfiles[key]=p;save();if(state.page==='artist')render();}}catch{}}finally{artistPending.delete(key);}}
let newReleases=Array.isArray(state.newReleasesCache?.items)?state.newReleasesCache.items:[],newReleasesBusy=false,newReleasesChecked=0,newReleasesKey='';
function releasesTasteKey(){return listeningTaste().map(t=>artistKey(t.artist)).join('|')+';'+state.hiddenArtists.join('|');}
async function loadNewReleases(){if(document.hidden||!listeningTaste().length||newReleasesBusy)return;const key=releasesTasteKey();if(newReleasesKey===key&&Date.now()-newReleasesChecked<60000)return;newReleasesBusy=true;newReleasesKey=key;newReleasesChecked=Date.now();try{const response=await fetch('/api/new-releases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(homePayload())});const body=await response.json();if(!response.ok||releasesTasteKey()!==key)return;newReleases=body.releases||[];state.newReleasesCache={items:newReleases,checkedAt:body.checkedAt};save();}catch{}finally{newReleasesBusy=false;if(state.page==='home'){const y=main.scrollTop;render();main.scrollTop=y;}}}
