function refreshActiveCatalog(){if(document.hidden||!navigator.onLine)return;if(state.page==='artist')loadArtistCollection(state.artist);else if(state.page==='artist-album')loadFullAlbum(state.albumId);else if(state.page==='home'){loadNewReleases();loadHome();}}
