function rememberFastArtist(profile){const records=state.fastArtistProfiles&&typeof state.fastArtistProfiles==='object'?state.fastArtistProfiles:{};records[artistKey(profile.name)]={profile,at:Date.now()};state.fastArtistProfiles=Object.fromEntries(Object.entries(records).sort((a,b)=>b[1].at-a[1].at).slice(0,8));}
const artistRechecks=new Map();
function scheduleArtistRecheck(name,profile){const key=artistKey(name),previous=artistRechecks.get(key);if(!profile.latestChecking){if(previous)clearTimeout(previous.timer);artistRechecks.delete(key);return;}const count=previous?.stamp===profile.verifiedAt?previous.count:0;if(count>=6)return;if(previous)clearTimeout(previous.timer);const record={stamp:profile.verifiedAt,count:count+1};record.timer=setTimeout(()=>{if(!document.hidden&&state.page==='artist'&&artistKey(state.artist)===key)loadArtistCollection(name,{partial:true});},1800);artistRechecks.set(key,record);}
for(const record of Object.values(state.fastArtistProfiles||{})){const profile=record?.profile;if(!profile?.id||!profile.name||!Array.isArray(profile.topSongs)||!Array.isArray(profile.albums))continue;artistCollections.set(profile.id,profile);if(record.at&&Date.now()-record.at<60000)artistCheckedAt.set(profile.id,record.at);queueMicrotask(()=>scheduleArtistRecheck(profile.name,profile));}
let hoverArtistTimer;
