function bindOrganizedSettings(){state.scrollTitles=true;state.reduceMotion=false;phone.classList.remove('reduce-title-motion','reduce-cover-motion');phone.style.setProperty('--lyrics-text-size',(Number(state.lyricsSize)||30)+'px');if(state.page!=='settings')return;const volume=main.querySelector('.settings-volume-input');volume.oninput=()=>{state.volume=Number(volume.value);window.VitraAudio.setVolume(state.volume);};volume.onchange=save;const data=main.querySelector('.data-saver-setting');data.onchange=()=>{state.dataSaver=data.checked;releaseArtistMotion();save();};const autoplay=main.querySelector('.autoplay-setting');autoplay.onchange=()=>{state.autoplaySimilar=autoplay.checked;save();};const size=main.querySelector('.lyrics-size-setting');size.value=String([26,30,34].includes(Number(state.lyricsSize))?state.lyricsSize:30);size.onchange=()=>{state.lyricsSize=Number(size.value);phone.style.setProperty('--lyrics-text-size',state.lyricsSize+'px');save();};main.querySelector('[data-refresh-lyrics]').onclick=()=>{lyricDocuments.clear();lyricSession.document=null;lyricSession.key='';fetchLyrics(true);notice('Consultando de nuevo las fuentes de letras…');};}

